@Composable
fun NvGlyph(icon: NvIcon, tint: Color, modifier: Modifier = Modifier) {
    val path = remember(icon) { iconPath(icon.data) }
    Canvas(modifier) {
        // SVG-семантика preserveAspectRatio="xMidYMid meet": равномерный масштаб,
        // глиф по центру контейнера.
        val s = minOf(
            size.width / icon.data.viewportWidth,
            size.height / icon.data.viewportHeight,
        )
        val dx = (size.width - icon.data.viewportWidth * s) / 2f
        val dy = (size.height - icon.data.viewportHeight * s) / 2f
        translate(dx, dy) {
            scale(s, s, pivot = Offset.Zero) {
                drawPath(path, tint)
            }
        }
    }
}
